const out = [];

for (const item of $input.all()) {
  const raw = item.json.From || item.json.from || '';
  const emailMatch = (raw.match(/<([^>]+)>/) || [])[1];
  const email = emailMatch ? emailMatch.trim() : (raw.includes('@') ? raw.trim() : '');
  let name = raw.replace(/<[^>]*>/g, '').replace(/"/g, '').trim();
  if ((!name || name === '') && email) name = email.split('@')[0];

  out.push({
    json: {
      ...item.json,
      UserName: name,
      Email: email,
    }
  });
}

return out;

// n8n Code node (JavaScript)
// Input: the incoming item(s) contain the Slack blocks JSON in item.json
// Output: item.json will be augmented with the Ticket fields to write to Sheets/Excel.

const out = [];

for (const item of $input.all()) {
  const src = item.json || {};
  const blocks = src.blocks || [];

  // Header (subject)
  const headerBlock = blocks.find(b => b.type === 'header');
  // const subject = headerBlock?.text?.text || '';
  const subject = $input.first().json.Subject;

  // Find first section that contains fields (the fields array from your template)
  const fieldsSection = blocks.find(b => b.type === 'section' && Array.isArray(b.fields));
  const fields = fieldsSection?.fields || [];

  // Helper to safely get field text by label
  const findFieldText = (label) => {
    const f = fields.find(ff => (ff.text || '').includes(label));
    return f ? (f.text || '') : '';
  };

  // Try to extract ticket id from Request ID field
  let ticketId = '';
  const reqText = findFieldText('Request ID') || findFieldText('RequestID') || '';
  if (reqText) {
    // extract contiguous digits
    const digits = reqText.match(/\d{6,}/);
    if (digits) ticketId = digits[0];
  }
  // fallback to provided JSON value if present
  if (!ticketId) ticketId = src.requestId || src.ticketId || '';

  // CreatedAt derived from TicketID prefix if possible (YYYYMMDD...), else today
  let createdAt = '';
  if (ticketId && ticketId.length >= 8) {
    const d = ticketId.slice(0,8); // YYYYMMDD
    createdAt = `${d.slice(0,4)}-${d.slice(4,6)}-${d.slice(6,8)}`;
  } else {
    createdAt = (new Date()).toISOString().slice(0,10);
  }

  // From/from email - prefer direct JSON fields if available
  const from = src.From || src.from || (() => {
    // parse markdown field "*Customer:*\n{{ $json.From }}" or "*Email:*"
    const f1 = findFieldText('*Customer:*') || findFieldText('*Customer:*\\') || '';
    const f2 = findFieldText('*Email:*') || '';
    // crude extraction: take everything after the last newline
    const extract = (t) => {
      const m = t.split('\n').pop().trim();
      return m.replace(/\*/g,'').replace(/\\\{|\{|\}/g,'').trim();
    };
    return extract(f1) || extract(f2) || '';
  })();

  const fromEmail = src.FromEmail || src.fromEmail || from || (src.email || '');

  // Snippet - try src.snippet, else parse the section text that uses snippet
  let snippet = src.snippet || '';
  if (!snippet) {
    const snippetSection = blocks.find(b => b.type === 'section' && b.text && b.text.text && b.text.text.includes('{{ $json.snippet'));
    if (snippetSection) snippet = '{{ $json.snippet }}';
  }

  // Body - look for the textual description (a section with text)
  let body = '';
  const issueSection = blocks.find(b => b.type === 'section' && b.text && b.text.text && b.text.text.includes('Issue Description') === false);
  // fallback: combine non-header, non-actions text blocks excluding fields block
  if (!body) {
    // try to find the short line present in the fields (first fields item sometimes contains issue sentence)
    const candidate = fields.map(f => f.text).join('\n');
    if (candidate && candidate.includes('The user interface')) {
      // remove markdown labels like *Customer:* etc.
      body = candidate.replace(/\*\w+:\*/g,'').replace(/\\n/g,'\n').trim();
    }
  }
  // more robust: look for any block containing plain sentence (example from provided JSON)
  if (!body) {
    const anyTextBlock = blocks.find(b => b.type === 'section' && b.text && /user interface|does not|not allow/i.test(b.text.text));
    if (anyTextBlock) {
      body = anyTextBlock.text.text.replace(/\{\{.*\}\}/g,'').trim();
    }
  }
  if (!body) body = src.body || '';

  // Status/priority
  let priority = '';
  const pr = findFieldText('Priority') || findFieldText('*Priority:*') || '';
  if (pr) {
    const p = pr.match(/P\d/);
    priority = p ? p[0] : pr.trim();
  }
  if (!priority) priority = src.priority || 'P1';
  const status = `${priority} / Open`;

  // Final item
  const result = {
    TicketID: ticketId || (new Date().getTime().toString()), // ensure something
    CreatedAt: createdAt,
    From: from || '{{ $json.From }}',
    FromEmail: fromEmail || '{{ $json.From }}',
    Subject: subject || '{{ $json.subject }}',
    Snippet: snippet || '{{ $json.snippet }}',
    Body: body || '',
    Status: status
  };

  // put into item.json so following nodes see fields as columns
  item.json = { ...item.json, ...result };

  out.push(item);
}

return out;
